### 四、增强功能实现

#### 1. **生成历史记录**
```tsx
const [history, setHistory] = useState<Array<{
  config: ImageGenConfig;
  imageData: string;
  timestamp: number;
}>>([]);

const addToHistory = (item: typeof history[0]) => {
  setHistory(prev => [item, ...prev.slice(0, 9)]);
};
```

