#### 3. **安全防护**
```typescript
// 在提交前过滤敏感词
const filterPrompt = (prompt: string) => {
  const blockedTerms = ['暴力', '仇恨言论'];
  return blockedTerms.some(term => prompt.includes(term)) 
    ? null 
    : prompt;
};
```

